import{_ as r}from"./chunks/stablediffusion_2026-07-22_215847_095.CMHOgVj2.js";import{_ as i,C as l,o as p,c as d,at as e,E as a,w as s}from"./chunks/framework.CY22Hent.js";const h="/assets/stablediffusion_202607162226.x1wu0pX4.png",c="/assets/ai_2026-07-25_144153_609.BzYqi_3v.png",g="/assets/ai_2026-07-25_144421_361.7zXzVWhf.png",A="/assets/stablediffusion_2026-07-16_155830_970.BIPmGL8B.png",u="/assets/stablediffusion_2026-07-16_220533_872.BIhCZ0wi.png",b="/assets/stablediffusion_2026-07-21_110014_176.BEmu8kqs.png",E="/assets/stablediffusion_2026-07-21_110041_432.CVSb_xhB.png",f="/assets/stablediffusion_2026-07-21_164650_227.4XKglqeC.png",k="/assets/stablediffusion_2026-07-17_173507_595.BfyH92ym.png",m="/assets/stablediffusion_2026-07-17_164931_305.ds-RMB2f.png",L=JSON.parse('{"title":"AI图像生成模型笔记","description":"","frontmatter":{"title":"AI图像生成模型笔记","date":"2026-07-18T00:00:00.000Z","lastUpdated":"2026-07-18T00:00:00.000Z","categories":["AI"],"tags":["图像生成","AI"]},"headers":[],"relativePath":"blogs/AI/AI图像生成模型笔记.md","filePath":"blogs/AI/AI图像生成模型笔记.md"}'),B={name:"blogs/AI/AI图像生成模型笔记.md"};function C(q,t,_,D,I,x){const n=l("MermaidChart"),o=l("ClientOnly");return p(),d("div",null,[t[0]||(t[0]=e('<p>[toc]</p><h1 id="ai图像生成模型笔记" tabindex="-1">AI图像生成模型笔记 <a class="header-anchor" href="#ai图像生成模型笔记" aria-label="Permalink to &quot;AI图像生成模型笔记&quot;">​</a></h1><h2 id="模型网站" tabindex="-1">模型网站 <a class="header-anchor" href="#模型网站" aria-label="Permalink to &quot;模型网站&quot;">​</a></h2><p>模型网站是可以提供用户下载模型的网站。用户可以在网站上找到不同的模型，根据自己的需求选择下载。</p><p><img src="'+h+'" alt="stablediffusion_202607162226.png" loading="lazy"></p><h3 id="hugging-face-模型网站-通用模型" tabindex="-1">Hugging Face 模型网站（通用模型） <a class="header-anchor" href="#hugging-face-模型网站-通用模型" aria-label="Permalink to &quot;Hugging Face 模型网站（通用模型）&quot;">​</a></h3><p><a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face官网：https://huggingface.co/</a></p><p>Hugging Face是全球最大 AI 开源模型仓库、AI 界 GitHub，行业标准模型托管平台，几乎所有主流开源模型都会首发于此。</p><p>在Hugging Face 模型网站中可以 下载 checkpoint 文件、复现模型、在线验证、二次开发、托管模型。</p><p>如图是 Hugging Face 模型网站的截图，用户可以在网站上找到不同的模型，根据自己的需求选择下载。 <img src="'+c+'" alt="ai_2026-07-25_144153_609.png" loading="lazy"></p><h3 id="civitai-模型网站-海外-ai-绘画模型" tabindex="-1">Civitai 模型网站（海外，AI 绘画模型） <a class="header-anchor" href="#civitai-模型网站-海外-ai-绘画模型" aria-label="Permalink to &quot;Civitai 模型网站（海外，AI 绘画模型）&quot;">​</a></h3><p><a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai官网：https://civitai.com/</a></p><p>Civitai 是全球最大 AI 绘画模型社区（海外）。该网站包含海量 SD/Flux 等文生图模型、Checkpoint 底模、LoRA、ControlNet、VAE、Embedding 等 AIGC 视觉模型。</p><p>适用人群：AI 绘画创作者、二次元 / 写实风格模型爱好者、Stable Diffusion 用户</p><p>如图是 Civitai 模型网站的截图，用户可以在网站上找到不同的模型，根据自己的需求选择下载。 <img src="'+g+'" alt="ai_2026-07-25_144421_361.png" loading="lazy"></p><h3 id="liblibai-哩布哩布-ai" tabindex="-1">LiblibAI（哩布哩布 AI） <a class="header-anchor" href="#liblibai-哩布哩布-ai" aria-label="Permalink to &quot;LiblibAI（哩布哩布 AI）&quot;">​</a></h3><p><a href="https://liblib.ai/" target="_blank" rel="noreferrer">LiblibAI官网：https://liblib.ai/</a></p><p>LiblibAI 是一个国内主流 AI 绘画 &amp; 视频模型社区。该网站包含海量 AI 模型，主要适配中文生态、可直接在线生成，主打图像 / 视频创意模型。</p><h3 id="modelscope-魔搭社区" tabindex="-1">ModelScope 魔搭社区 <a class="header-anchor" href="#modelscope-魔搭社区" aria-label="Permalink to &quot;ModelScope 魔搭社区&quot;">​</a></h3><p><a href="https://modelscope.cn/" target="_blank" rel="noreferrer">ModelScope官网：https://modelscope.cn/</a></p><p>ModelScope 魔搭社区是国内主流 AI 模型开源社区（阿里达摩院联合 CCF）</p><p>该网站包含海量中文模型（通义千问 Qwen、ChatGLM、百川、DeepSeek 等），兼顾海外主流模型镜像；一键推理、微调、模型部署、MaaS 服务、免费算力体验；中文文档完善、国内高速下载。</p><h2 id="图像生成模型简史" tabindex="-1">图像生成模型简史 <a class="header-anchor" href="#图像生成模型简史" aria-label="Permalink to &quot;图像生成模型简史&quot;">​</a></h2><p>AI图像生成技术的发展大致经历了三个阶段：</p><p><strong>第一阶段：GAN时代（2014-2020）</strong></p><ul><li>GAN（生成对抗网络）是最早实现图像生成的技术</li><li>原理：两个网络相互对抗——生成器生成假图像，判别器区分真假</li><li>代表模型：DCGAN、StyleGAN、ProGAN</li><li>局限：训练不稳定，容易生成模糊或畸形图像</li></ul><p><strong>第二阶段：VAE时代（2013-2022）</strong></p><ul><li>VAE（变分自编码器）通过编码-解码方式生成图像</li><li>原理：先将图像压缩到潜在空间，再从潜在空间还原</li><li>代表模型：VAE、β-VAE</li><li>局限：生成质量不如GAN，图像不够清晰</li></ul><p><strong>第三阶段：Diffusion时代（2020-至今）</strong></p><ul><li>Diffusion（扩散模型）通过逐步去噪生成图像</li><li>原理：从随机噪声开始，逐步去除噪声生成清晰图像</li><li>代表模型：Stable Diffusion、DALL-E、MidJourney、Flux</li><li>优势：生成质量高，训练稳定，可控性强</li></ul><p><span style="color:red;">目前主流的AI图像生成模型几乎都基于Diffusion架构。</span></p><hr><h2 id="图像生成模型谱系" tabindex="-1">图像生成模型谱系 <a class="header-anchor" href="#图像生成模型谱系" aria-label="Permalink to &quot;图像生成模型谱系&quot;">​</a></h2><h3 id="基底模型与微调模型" tabindex="-1">基底模型与微调模型 <a class="header-anchor" href="#基底模型与微调模型" aria-label="Permalink to &quot;基底模型与微调模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>类比</th><th>说明</th></tr></thead><tbody><tr><td><strong>基底模型</strong></td><td>编程语言的基础语法</td><td>官方发布的原始模型，功能通用但不专精</td></tr><tr><td><strong>微调模型</strong></td><td>基于基础语法的框架/库</td><td>在基底模型上用特定数据集训练和微调优化，专精某一领域</td></tr></tbody></table><p><span style="color:red;">基底模型就像Python语言本身，微调模型就像Django、Flask这样的框架，是在基础之上的专业化封装。</span></p><h3 id="模型关系图" tabindex="-1">模型关系图 <a class="header-anchor" href="#模型关系图" aria-label="Permalink to &quot;模型关系图&quot;">​</a></h3>',37)),a(o,null,{default:s(()=>[a(n,{code:"graph%20TD%0A%20%20%20%20subgraph%20%E5%9F%BA%E5%BA%95%E6%A8%A1%E5%9E%8B%0A%20%20%20%20%20%20%20%20SD1%5BStable%20Diffusion%201.5%5D%0A%20%20%20%20%20%20%20%20SDXL%5BStable%20Diffusion%20XL%5D%0A%20%20%20%20%20%20%20%20SD3%5BStable%20Diffusion%203%5D%0A%20%20%20%20%20%20%20%20FLUX%5BFlux%5D%0A%20%20%20%20%20%20%20%20DALLE%5BDALL-E%5D%0A%20%20%20%20%20%20%20%20MJ%5BMidJourney%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20SD%201.5%20%E5%BE%AE%E8%B0%83%E6%A8%A1%E5%9E%8B%0A%20%20%20%20%20%20%20%20SD1%20--%3E%20AV4%5BAnything%20V4.5%5D%0A%20%20%20%20%20%20%20%20SD1%20--%3E%20MM%5BMeinaMix%5D%0A%20%20%20%20%20%20%20%20SD1%20--%3E%20AOM%5BAbyssOrangeMix%5D%0A%20%20%20%20%20%20%20%20SD1%20--%3E%20RV%5BRealistic%20Vision%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20SDXL%20%E5%BE%AE%E8%B0%83%E6%A8%A1%E5%9E%8B%0A%20%20%20%20%20%20%20%20SDXL%20--%3E%20JUG%5BJuggernaut%20XL%5D%0A%20%20%20%20%20%20%20%20SDXL%20--%3E%20RVXL%5BRealistic%20Vision%20XL%5D%0A%20%20%20%20%20%20%20%20SDXL%20--%3E%20DREAM%5BDreamShaper%20XL%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20SD%203%20%E5%BE%AE%E8%B0%83%E6%A8%A1%E5%9E%8B%0A%20%20%20%20%20%20%20%20SD3%20--%3E%20SD3T%5BSD%203%20Turbo%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20Flux%20%E5%8F%98%E4%BD%93%0A%20%20%20%20%20%20%20%20FLUX%20--%3E%20FLUXS%5BFlux.1-schnell%5D%0A%20%20%20%20%20%20%20%20FLUX%20--%3E%20FLUXD%5BFlux.1-dev%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20style%20SD1%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20SDXL%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20SD3%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20FLUX%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20DALLE%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20MJ%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A",showToolbar:"1"})]),_:1}),t[1]||(t[1]=e('<p><strong>基底模型举例</strong>：</p><ul><li><strong>Stable Diffusion 1.5</strong>：最基础的Diffusion模型，资源需求低，社区生态成熟。由Stability AI开发。</li><li><strong>Stable Diffusion XL</strong>：升级版，支持更高分辨率和更好的细节，由Stability AI开发。</li><li><strong>Stable Diffusion 3</strong>：最新版，支持多模态输入，由Stability AI开发。</li><li><strong>Flux</strong>：新一代模型，生成质量极高。开源，社区支持良好。由Black Forest Labs（黑森林实验室）开发‌。</li><li><strong>DALL-E</strong>：基于Transformer架构，生成质量高。由OpenAI开发。闭源模型</li><li><strong>MidJourney</strong>：基于Diffusion架构，生成质量高，训练稳定。社区生态成熟。闭源模型</li></ul><p><strong>微调模型举例</strong>：</p><ul><li><strong>Flux.1-schnell</strong>：基于Flux 1.0微调，生成质量极高，速度较快</li><li><strong>Flux.1-dev</strong>：基于Flux 1.0微调，生成质量极高，速度较慢</li><li><strong>SD 3 Turbo</strong>：基于SD 3微调，支持多模态输入，生成质量极高。</li><li><strong>Anything V4.5</strong>：基于SD 1.5微调，专精动漫风格。</li><li><strong>MeinaMix</strong>：基于SD 1.5微调，专精动漫风格。</li><li><strong>Realistic Vision</strong>：基于SD 1.5/SDXL微调，专精写实风格。</li><li><strong>Juggernaut XL</strong>：基于SDXL微调，综合能力强。</li></ul><hr><h2 id="模型类型" tabindex="-1">模型类型 <a class="header-anchor" href="#模型类型" aria-label="Permalink to &quot;模型类型&quot;">​</a></h2><p>模型是指通过海量数据 + 学习算法训练而来,得到的一个神经网络模型。以模型文件的形式存储。</p><p><span style="color:red;">通过给模型不断地喂养数据,模型会学习到数据的规律和特征。这些规律和特征会被存储在模型文件上。</span></p><p><span style="color:blue;">即模型文件存储的不是训练数据本身，而是从训练数据上提取出来的规则和特征。调用模型就是通过模型参数来激发出模型内部的这些规则和特征，从而让模型生成新的数据。</span></p><h3 id="基底模型" tabindex="-1">基底模型 <a class="header-anchor" href="#基底模型" aria-label="Permalink to &quot;基底模型&quot;">​</a></h3><p><strong>基底模型</strong>: 基底模型是官方发布的原始模型。就像编程语言的基础语法，功能通用但不专精。</p><h3 id="微调模型" tabindex="-1">微调模型 <a class="header-anchor" href="#微调模型" aria-label="Permalink to &quot;微调模型&quot;">​</a></h3><p><strong>微调模型</strong>: 模型微调是指在已有的基底模型的基础上，通过给基底模型训练特定数据集来改进模型的性能。从而让基底模型能够专精某一领域。</p><p>如图所示 <img src="'+A+'" alt="stablediffusion_2026-07-16_155830_970.png" loading="lazy"></p><h2 id="checkpoint-模型" tabindex="-1">checkpoint 模型 <a class="header-anchor" href="#checkpoint-模型" aria-label="Permalink to &quot;checkpoint 模型&quot;">​</a></h2><h3 id="什么是checkpoint-检查点" tabindex="-1">什么是checkpoint 检查点？ <a class="header-anchor" href="#什么是checkpoint-检查点" aria-label="Permalink to &quot;什么是checkpoint 检查点？&quot;">​</a></h3><p>checkpoint 是计算机专业术语。最早用于定期保存计算机程序的运行状态，防止断电、死机、服务器中断导致程序作废，可从检查点继续运行，不必从头跑。</p><p>checkpoint 类似游戏存档、马拉松打卡点：通过备份计算机程序的运行状态，记录程序的进度，方便程序后续恢复。</p><p>当我们再进行模型训练和模型微调时。由于模型的参数量很大，训练时间也很长。因此为了保存模型的训练进度，会定期对模型进行备份处理。这些备份保存下来的模型文件就是 checkpoint 模型文件。</p><p><span style="color:red;">注意：每一个 checkpoint 模型文件都是一个独立的完整的模型文件。因此可以将checkpoint 模型理解为大模型在不同时期下的备份。</span></p><h3 id="checkpoint模型文件的作用" tabindex="-1">checkpoint模型文件的作用 <a class="header-anchor" href="#checkpoint模型文件的作用" aria-label="Permalink to &quot;checkpoint模型文件的作用&quot;">​</a></h3><ol><li>故障恢复续训：中断后可加载最近 checkpoint 检查点，从而继续训练，避免从头重来、浪费算力。</li><li>保存模型训练进度：防止断电、死机、服务器中断导致模型训练失败。</li><li>模型版本留存：保存不同轮次、最佳验证效果的 checkpoint，挑选最优版本部署。</li><li>模型审计与回溯：留存训练版本，方便排查模型效果问题、做版本管理</li><li>方便后续的微调，无需从头开始训练。</li></ol><p><span style="color:red;">简而言之，checkpoint 就是模型在不同时期的存档备份文件；名字源自通用计算机长任务断点存档技术，被深度学习沿用解决长时大模型训练的中断风险与版本管理问题。</span></p><h3 id="如何生成-checkpoint-文件" tabindex="-1">如何生成 checkpoint 文件 <a class="header-anchor" href="#如何生成-checkpoint-文件" aria-label="Permalink to &quot;如何生成 checkpoint 文件&quot;">​</a></h3><ul><li>① 通过对模型进行微调训练，生成一个新的模型。就可以导出为 checkpoint 文件。</li><li>② 通过对多个模型进行融合训练，生成一个新的模型。就可以导出为 checkpoint 文件。</li></ul><p><img src="'+u+'" alt="stablediffusion_2026-07-16_220533_872.png" loading="lazy"></p><h3 id="checkpoint-文件内容-ckpt-文件后缀格式" tabindex="-1">checkpoint 文件内容（.ckpt 文件后缀格式） <a class="header-anchor" href="#checkpoint-文件内容-ckpt-文件后缀格式" aria-label="Permalink to &quot;checkpoint 文件内容（.ckpt 文件后缀格式）&quot;">​</a></h3><p><span style="color:red;">注意：每一个 checkpoint 模型文件都是一个独立的完整的模型文件。因此可以将checkpoint 模型理解为大模型在不同时期下的备份。</span></p><p>一个完整 checkpoint 文件包含以下：</p><ul><li>模型权重参数（模型参数的权重和偏置）</li><li>训练状态（模型的训练进度、损失函数值等）</li><li>其他元数据（如模型名称、训练配置等）</li><li>其他可执行代码（如模型推理代码、训练代码等）</li><li>....</li></ul><p>这些内容会被压缩存储在 checkpoint 模型文件中。当需要对继续训练时，会从 checkpoint 模型文件中提取模型参数和训练状态，从而恢复模型的运行状态。</p><p><span style="color:red;">注意：checkpoint 模型文件的后缀是 .ckpt</span></p><h3 id="模型权重参数文件-safetensors-文件后缀格式" tabindex="-1">模型权重参数文件（.safetensors 文件后缀格式） <a class="header-anchor" href="#模型权重参数文件-safetensors-文件后缀格式" aria-label="Permalink to &quot;模型权重参数文件（.safetensors 文件后缀格式）&quot;">​</a></h3><p>由于大多数使用模型的情况下，我们只需要用到模型的权重参数，其他数据用不到。因此目前的主流做法是将 checkpoint 模型文件转换为 <strong>.safetensors</strong> 文件格式。</p><p><span style="color:red;">.safetensors 文件是从完整 checkpoint 文件里提取、精简、转换出来的模型参数权重版本。整个.safetensors文件 只保留模型权重参数，没有其他相关数据等。</span></p><p>同时 <strong>.safetensors</strong> 文件由于去掉了优化器、训练日志、元信息等多余内容，因此是一种体积更小、加载更快的文件格式。它无法用于模型训练,只能用于模型推理。</p><p>==我们通常从模型网站上下载的模型文件都是 <strong>.safetensors</strong> 文件格式的。==</p><h3 id="checkpoint-模型的三个组件" tabindex="-1">Checkpoint 模型的三个组件 <a class="header-anchor" href="#checkpoint-模型的三个组件" aria-label="Permalink to &quot;Checkpoint 模型的三个组件&quot;">​</a></h3><p>一个完整的Checkpoint 模型通常会包含以下三个组件：</p><ul><li>UNet（扩散主干模型）：负责图像生成</li><li>CLIP（文本编码器）：负责将文本和图像转化为数字向量</li><li>VAE（变分自编码器）：负责图像编码和解码</li></ul><p>在SD1.5 时代绝大多数图像生成模型都是 Checkpoint 格式（即模型内部包含这三个组件）。但是随着新模型（SDXL、Wan、Qwen 等）的参数规模越来越大，打包成一个 Checkpoint 格式的模型文件太臃肿，也不方便单独升级某个组件。</p><p>因此目前的主流做法是将图像生成模型拆分成三个独立的组件文件。把UNet、CLIP、VAE 拆成三个独立的 <code>.safetensors</code> 文件，三个文件组合起来才是一个完整的Checkpoint 模型。</p><blockquote><p>为什么新一代的模型都改成拆分式？</p></blockquote><p>主要原因如下</p><ol><li>各个组件可单独优化：某个组件优化了，只需要替换对应文件即可。</li><li>组件可复用：同一个文本编码器、同一个 VAE，可以给同系列的多个主干模型共用。</li><li>体积可控：大模型单个文件动辄几十 GB，拆分后每个文件体积更合理，下载、传输、容错性都更好。</li></ol><p><span style="color:red;">注意：目前新一代的图像生成模型的三个组件也不是互相通用的。例如 SD1.5、SDXL、Wan 视频、Qwen 等模型的三个组件不能直接互相搭配。</span></p><h4 id="unet-扩散主干模型-核心组件" tabindex="-1">UNet（扩散主干模型，核心组件） <a class="header-anchor" href="#unet-扩散主干模型-核心组件" aria-label="Permalink to &quot;UNet（扩散主干模型，核心组件）&quot;">​</a></h4><p>由于目前主流的图像生成模型都是采用的Diffusion架构，因此 UNet 是图像生成模型中负责图像生成的核心组件。</p><p>UNet的工作就是在满是噪点的草稿上，如何一步一步擦掉噪点、画出符合要求的画面。</p><h4 id="clip-文本编码器" tabindex="-1">CLIP（文本编码器） <a class="header-anchor" href="#clip-文本编码器" aria-label="Permalink to &quot;CLIP（文本编码器）&quot;">​</a></h4><p>CLIP（文本编码器）核心能力是把「人类自然语言」和「图像特征」映射到同一套数字语言里。</p><p>CLIP（文本编码器）的作用实际有两个。</p><ul><li>文本编码：将文本描述转换为数字向量。</li><li>图像编码：把图片也转成同格式的数字向量。</li></ul><p><span style="color:red;">注意：不同的图像生成模型需要搭配各自对应的 CLIP 组件，才能有更好的图像生成效果。错配会直接偏色、模糊、崩坏。</span></p><h4 id="vae-变分自编码器-图像编码解码组件" tabindex="-1">VAE（变分自编码器，图像编码解码组件） <a class="header-anchor" href="#vae-变分自编码器-图像编码解码组件" aria-label="Permalink to &quot;VAE（变分自编码器，图像编码解码组件）&quot;">​</a></h4><p><span style="color:red;">VAE（Variational Autoencoder，变分自编码器）用于负责图像编码和解码的组件。</span></p><p><strong>工作原理</strong>：</p><ul><li><strong>图像编码</strong>：将正常 RGB 图像压缩到潜在空间。</li><li><strong>图像解码</strong>：将潜在空间图像还原为 RGB 图像。</li></ul><p><strong>通俗解释</strong>：VAE 就像一个图像翻译器，在人类能看懂的RGB图像和AI内部使用的潜在空间图像压缩格式之间转换。</p><p><strong>常见用途</strong>：</p><ul><li>改善图像颜色和细节</li><li>修复画面发灰、偏色问题</li><li>提升图像清晰度</li></ul><p><strong>常见 VAE</strong>：</p><ul><li><code>kl-f8-anime2</code>：适合动漫风格</li><li><code>SDXL VAE</code>：SDXL 模型专用</li><li><code>vae-ft-mse-840000-ema-pruned</code>：通用高质量 VAE</li></ul><p><span style="color:red;">注意：不同的图像生成模型需要搭配各自对应的 VAE 组件才能有更好的图像生成效果。错配会直接偏色、模糊、崩坏。</span></p><h2 id="附属扩展" tabindex="-1">附属扩展 <a class="header-anchor" href="#附属扩展" aria-label="Permalink to &quot;附属扩展&quot;">​</a></h2><p>早期如果我们想要给图像生成模型实现更复杂，更定制化的功能。只能对整个模型本体进行微调的手段。</p><p>但是随着时代和技术的进步，开发者可以通过对图像模型进行微调，扩展，插件等各个方式，来实现更好的效果。</p><p><span style="color:red;">附属扩展更像是对图像模型的补充和优化。这些附属扩展有的是另一个模型，有的是插件,有的可以独立运行，有的必须依赖于图像模型才能运行。</span></p><h3 id="embedding-模型-文本嵌入模型-补充扩展模型的文本理解能力" tabindex="-1">Embedding 模型（文本嵌入模型，补充扩展模型的文本理解能力） <a class="header-anchor" href="#embedding-模型-文本嵌入模型-补充扩展模型的文本理解能力" aria-label="Permalink to &quot;Embedding 模型（文本嵌入模型，补充扩展模型的文本理解能力）&quot;">​</a></h3><p><img src="'+b+'" alt="stablediffusion_2026-07-21_110014_176.png" loading="lazy"></p><blockquote><p>为什么会有Embedding 模型？</p></blockquote><p>早期如果一个图像生成模型出现的时候比较早，那么过了一段时间后，该图像生成模型就可能无法识别新出现的词语。因为该图像生成模型的训练数据中，没有包含新出现的词语。</p><p>而如果对图像生成模型进行微调的话，虽然可以识别新出现的词语，但是由于图像生成模型的参数量是很大，微调时间也很长，这样会导致效率太慢。</p><p>之后就出现了 Embedding 模型。通过像插件一样的方式，让图像生成模型 搭配 embedding 模型,就可以补充扩展该图像生成模型的文本理解能力，让其识别新出现的词语。</p><p>这样的方式比微调更轻量化，效率更高。</p><p><span style="color:red;"> 通俗解释：Embedding 模型就像给图像生成模型一本新字典，里面收录了一些新词，从而让图像生成模型理解这些新词的含义。Embedding 模型补充扩展了图像生成模型对文本的理解能力。</span></p><blockquote><p>Embedding 模型的作用</p></blockquote><ul><li>优化提示词效果</li><li>补充扩展模型对文本的理解能力，让模型能够识别新出现的词语。</li><li>扩展负面提示词，来消除图片的负面效果</li><li>扩展正面提示词，来增强图片的正面效果</li></ul><blockquote><p>Embedding 模型的工作原理</p></blockquote><p>Embedding 模型的工作原理是通过学习文本与图像之间的关系，将文本转换为向量表示。这些向量表示可以用于生成图像。</p><p>然后Embedding 模型本身体积很小，通常只有几 KB ~ 几 MB。因此学习的成本很低，速度也很快。通过少量图片（通常3-10张）训练，就能让Embedding 模型学会一个新的&quot;单词&quot;。</p><p><span style="color:red;">Embedding 模型无法独立运行，需要依赖于对应的 图像生成模型。然后通过这种方式，从而让图像生成模型理解文本的含义。</span></p><h3 id="lora-模型-低秩适配模型-强化模型的图像生成能力" tabindex="-1">Lora 模型（低秩适配模型，强化模型的图像生成能力） <a class="header-anchor" href="#lora-模型-低秩适配模型-强化模型的图像生成能力" aria-label="Permalink to &quot;Lora 模型（低秩适配模型，强化模型的图像生成能力）&quot;">​</a></h3><p><img src="'+E+'" alt="stablediffusion_2026-07-21_110041_432.png" loading="lazy"></p><p>LoRA（Low-Rank Adaptation，低秩适配）是目前最主流的轻量化模型微调方案。</p><blockquote><p>为什么会会有Lora 模型？</p></blockquote><p>当我们想要对模型本体进行微调的时候，由于模型本身的参数量是很大的，因此微调时间也很长，这样会导致效率太慢。因此出现了 Lora 模型。</p><p><span style="color:red;">Lora模型是完全基于模型本体的一小部分模型参数进行训练的微调产物。因此Lora模型不可以独立运行，只能搭配对应的模型本体一起使用。</span></p><p>由于Lora模型本身微调的参数量很小。因此Lora模型的体积很小，体积通常只有几十 MB ~ 几百 MB。</p><p><img src="'+f+'" alt="stablediffusion_2026-07-21_164650_227.png" loading="lazy"></p><blockquote><p>Lora 模型的作用</p></blockquote><p><span style="color:red;">通过模型本体 + 对应的 Lora 模型一起使用，可以为模型添加新的模型参数或者强化原有的模型参数。从而提升模型的图像生成能力。</span></p><p><strong>通俗解释</strong>：Lora 模型就像给模型本体 定制了一个扩展包，让它能够实现各种扩展功能，但不改变模型本身。</p><p><strong>常见用途</strong>：</p><ul><li>添加特定画风（动漫、写实、赛博朋克等）</li><li>学习特定人物特征</li><li>增强模型在特定领域的表现</li></ul><blockquote><p>Lora 模型的工作原理</p></blockquote><p><strong>工作原理</strong>：通过低秩矩阵分解技术，在不修改原模型参数权重的情况下，通过补丁插件的方式为模型添加新的模型参数或者强化原有的模型参数。</p><h3 id="controlnet组件-控制网络" tabindex="-1">ControlNet组件（控制网络） <a class="header-anchor" href="#controlnet组件-控制网络" aria-label="Permalink to &quot;ControlNet组件（控制网络）&quot;">​</a></h3><p>ControlNet 是一个强大的控制工具，允许用户通过辅助图像精确控制生成结果。</p><p><strong>工作原理</strong>：在生成过程中，额外引入一个控制网络，根据辅助图像（如线稿、深度图、姿势图）来引导图像生成，确保图像生成的结果符合预期的结构和布局。</p><p><strong>通俗解释</strong>：就像给AI一张草图或布局图或深度图或姿势图等，然后让它按照这个框架来画画。</p><p><strong>常见 ControlNet 类型</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>作用</th><th>使用场景</th></tr></thead><tbody><tr><td><strong>Canny</strong></td><td>边缘检测，控制轮廓</td><td>线稿上色、轮廓控制</td></tr><tr><td><strong>OpenPose</strong></td><td>姿态估计，控制人物姿势</td><td>人物动作控制</td></tr><tr><td><strong>Depth</strong></td><td>深度图，控制空间关系</td><td>场景布局、透视控制</td></tr><tr><td><strong>Segmentation</strong></td><td>分割图，控制区域</td><td>区域风格化、内容替换</td></tr><tr><td><strong>Tile</strong></td><td>平铺控制</td><td>高清修复、图像扩展</td></tr><tr><td><strong>Scribble</strong></td><td>涂鸦控制</td><td>草图生成</td></tr></tbody></table><p><strong>使用步骤</strong>：</p><ol><li>准备一张辅助图像（如线稿、姿势图）</li><li>使用对应的 ControlNet 模型处理辅助图像</li><li>将处理结果连接到采样器节点</li><li>AI模型 会根据辅助图像的结构进行生成</li></ol><h3 id="upscaler-放大模型" tabindex="-1">Upscaler 放大模型 <a class="header-anchor" href="#upscaler-放大模型" aria-label="Permalink to &quot;Upscaler 放大模型&quot;">​</a></h3><p>Upscaler（图像放大模型）用于将低分辨率图像放大到更高分辨率，同时增强细节。</p><p><strong>工作原理</strong>：通过深度学习技术，在放大图像的同时填充缺失的细节，避免像素化。</p><p><strong>通俗解释</strong>：就像用放大镜看图片，但看到的不是模糊的像素，而是清晰的细节。</p><p><strong>常见模型</strong>：</p><ul><li><strong>ESRGAN</strong>：经典放大模型，效果好</li><li><strong>4x-UltraSharp</strong>：高质量4倍放大</li><li><strong>RealESRGAN</strong>：专门优化真实照片放大</li></ul><h3 id="controlnet-控制网络" tabindex="-1">controlNet 控制网络 <a class="header-anchor" href="#controlnet-控制网络" aria-label="Permalink to &quot;controlNet 控制网络&quot;">​</a></h3><blockquote><p>什么是 ControlNet ？</p></blockquote><p>图像生成模型生成图像，就像抽卡一样。例如，我想生成一张做出特定的姿势和动作的人物的图像（抽烟，跳舞，运动等）。通常情况下，就算有详细精准的提示词的把控下，也不能完全确保人物的姿势和动作次次符合预期。</p><p>因此就出现了 ControlNet 控制网络，它由 Lvmin Zhang 等人于 2023 年提出，迅速成为图像生成领域的标配工具。</p><p>ControlNet 控制网络是一个神经网络模型，允许用户通过辅助图像方便快捷的控制图像人物的姿势和动作。</p><p><span style="color:red;">ControlNet 是现代 AI 图像生成不可或缺的工具，掌握它可以大幅提升生成的可控性和创意表达能力。</span></p><blockquote><p>ControlNet 控制网络的工作原理</p></blockquote><p>ControlNet 是一种端到端的空间条件控制神经网络架构，通过外挂式旁路分支，将额外的空间约束信号（姿态、深度、边缘、语义分割图等）注入预训练扩散 UNet，在完全不损失底模原生生成能力的前提下，实现对生成画面结构的精准控制。</p><p><span style="color:red;">ControlNet 控制网络无法独立生成图像，必须配合对应的主模型本体协同工作。</span></p><p>如图所示 <img src="'+r+`" alt="stablediffusion_2026-07-22_215847_095.png" loading="lazy"></p><blockquote><p>ControlNet 控制网络的核心功能</p></blockquote><table tabindex="0"><thead><tr><th>功能类别</th><th>具体能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>结构控制</strong></td><td>边缘检测、姿态估计、深度图</td><td>精确控制图像的结构和布局</td></tr><tr><td><strong>内容控制</strong></td><td>分割图、关键点检测</td><td>指定图像中不同区域的内容</td></tr><tr><td><strong>风格控制</strong></td><td>风格迁移、调色板控制</td><td>将参考图像的风格应用到生成结果</td></tr><tr><td><strong>修复增强</strong></td><td>高清修复、图像扩展</td><td>对现有图像进行修复和放大</td></tr></tbody></table><h4 id="常用-controlnet-控制网络的模型" tabindex="-1">常用 ControlNet 控制网络的模型 <a class="header-anchor" href="#常用-controlnet-控制网络的模型" aria-label="Permalink to &quot;常用 ControlNet 控制网络的模型&quot;">​</a></h4><p>ControlNet 控制网络有多种类型的模型，每个类型的模型都有其特定的功能和适用场景。以下是一些常用的 ControlNet 控制网络模型：</p><table tabindex="0"><thead><tr><th>序号</th><th>模型名称</th><th>作用</th><th>使用场景</th><th>特点</th></tr></thead><tbody><tr><td>1</td><td><strong>Canny</strong>（边缘检测）</td><td>检测图像边缘，控制轮廓形状</td><td>线稿上色、轮廓控制、保持特定形状</td><td>对线条要求不高，草图也能使用</td></tr><tr><td>2</td><td><strong>OpenPose</strong>（姿态估计）</td><td>检测人体关键点，控制人物姿势和动作</td><td>人物动作控制、多人互动场景、角色动画</td><td>支持单人、多人姿态检测</td></tr><tr><td>3</td><td><strong>Depth</strong>（深度图）</td><td>生成深度图，控制空间关系和透视</td><td>场景布局、透视控制、3D 效果增强</td><td>支持多种深度估计模型</td></tr><tr><td>4</td><td><strong>Segmentation</strong>（分割图）</td><td>将图像分割为不同区域，分别控制</td><td>区域风格化、内容替换、多主题生成</td><td>需要精确的分割标注</td></tr><tr><td>5</td><td><strong>Tile</strong>（平铺控制）</td><td>通过局部图像块控制生成</td><td>高清修复、图像扩展、细节增强</td><td>对显存要求较低</td></tr><tr><td>6</td><td><strong>Scribble</strong>（涂鸦控制）</td><td>根据简单涂鸦生成图像</td><td>草图生成、创意快速表达</td><td>对绘画技巧要求极低</td></tr></tbody></table><h4 id="进阶-controlnet-控制网络的模型" tabindex="-1">进阶 ControlNet 控制网络的模型 <a class="header-anchor" href="#进阶-controlnet-控制网络的模型" aria-label="Permalink to &quot;进阶 ControlNet 控制网络的模型&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型名称</th><th>功能</th><th>使用场景</th></tr></thead><tbody><tr><td><strong>Lineart</strong></td><td>提取艺术线条</td><td>艺术线稿上色</td></tr><tr><td><strong>Normal Map</strong></td><td>法线贴图控制</td><td>3D 渲染、光照控制</td></tr><tr><td><strong>HED</strong></td><td>软边缘检测</td><td>柔和轮廓控制</td></tr><tr><td><strong>MLSD</strong></td><td>直线和几何检测</td><td>建筑、室内设计</td></tr><tr><td><strong>Softedge</strong></td><td>软边缘控制</td><td>水彩、手绘风格</td></tr></tbody></table><h2 id="文生图-text-to-image" tabindex="-1">文生图（Text-to-Image） <a class="header-anchor" href="#文生图-text-to-image" aria-label="Permalink to &quot;文生图（Text-to-Image）&quot;">​</a></h2><p><span style="color:blue;">文生图的核心比喻：AI从一张满是雪花噪点的空白画布中，按照文字指令一步步擦除噪点，最终画出完整图片。</span></p><h3 id="文生图的基本逻辑" tabindex="-1">文生图的基本逻辑 <a class="header-anchor" href="#文生图的基本逻辑" aria-label="Permalink to &quot;文生图的基本逻辑&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入提示词（例如：&quot;画一个穿红色衣服的女孩&quot;）</span></span>
<span class="line"><span>  -&gt; 文本模型将提示词转化为AI向量语言</span></span>
<span class="line"><span>  -&gt; 把AI向量语言发送给图像生成模型 </span></span>
<span class="line"><span>  -&gt; 图像生成模型先随机生成一张完全杂乱、没有任何内容的噪点图，相当于一张全是雪花的图片。</span></span>
<span class="line"><span>  -&gt; 图像生成模型根据你给的提示词要求，分几十步慢慢清理噪点。每一步都修正噪点图、使其贴合提示词要求。</span></span>
<span class="line"><span>  -&gt; 图像生成模型当迭代步数使用完后，就会生成一张符合要求的图。(如果步数太少，生成的图可能会有缺陷)。此时人类无法直接识别该图。</span></span>
<span class="line"><span>  -&gt; 然后将符合要求的图通过图像编码解码模型转换为人类能识别的图像结果。</span></span>
<span class="line"><span>  -&gt; 最后将生成的图像输出到本地。</span></span></code></pre></div><h3 id="文生图的工作原理" tabindex="-1">文生图的工作原理 <a class="header-anchor" href="#文生图的工作原理" aria-label="Permalink to &quot;文生图的工作原理&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 步骤1: 输入提示词（例如：&quot;画一个穿红色衣服的女孩&quot;）</span></span>
<span class="line"><span>- 步骤2: CLIP文本编码器将提示词转换为AI语言（条件向量）</span></span>
<span class="line"><span>- 步骤3: 在图像生成模型的潜空间中，随机采样生成一张空白潜在图像（充满随机噪点）。相当于一张全是雪花噪点的图片。</span></span>
<span class="line"><span>- 步骤4: 采样器根据AI语言（条件向量）逐步迭代去除潜在图像的噪点，生成清晰的潜在图像。</span></span>
<span class="line"><span>- 步骤5: VAE解码器将潜在图像转换为 RGB 像素图像</span></span>
<span class="line"><span>- 步骤6: 输出最终的 RGB 像素图像（例如：一个穿红色衣服的女孩）</span></span></code></pre></div><blockquote><p>核心组件</p></blockquote><table tabindex="0"><thead><tr><th>组件</th><th>作用</th><th>类比</th></tr></thead><tbody><tr><td>CLIP文本编码器</td><td>将文本转换为向量</td><td>翻译官</td></tr><tr><td>UNet 模型</td><td>执行去噪计算</td><td>画师的手</td></tr><tr><td>KSampler</td><td>控制去噪过程</td><td>画画的步骤</td></tr><tr><td>VAE</td><td>编码/解码图像</td><td>显影剂</td></tr></tbody></table><h3 id="文生图工作流示例" tabindex="-1">文生图工作流示例 <a class="header-anchor" href="#文生图工作流示例" aria-label="Permalink to &quot;文生图工作流示例&quot;">​</a></h3><p>用流程图展示文生图工作流</p>`,138)),a(o,null,{default:s(()=>[a(n,{code:"graph%20TD%0A%20%20%20%20subgraph%20%E8%BE%93%E5%85%A5%E5%B1%82%0A%20%20%20%20%20%20%20%20A%5B%E7%94%A8%E6%88%B7%E8%BE%93%E5%85%A5%E6%8F%90%E7%A4%BA%E8%AF%8D%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%0A%20%20%20%20%20%20%20%20B%5BCLIP%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDCLIP%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20C%5BCLIP%20Text%20Encode%3Cbr%2F%3E%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E5%9B%BE%E5%83%8F%E7%94%9F%E6%88%90%0A%20%20%20%20%20%20%20%20D%5BUNet%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDAI%E7%94%BB%E5%9B%BE%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20E%5BEmpty%20Latent%20Image%3Cbr%2F%3E%E7%A9%BA%E7%99%BD%E6%BD%9C%E5%9C%A8%E5%9B%BE%E5%83%8F%5D%0A%20%20%20%20%20%20%20%20F%5BKSampler%3Cbr%2F%3EK%E9%87%87%E6%A0%B7%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E5%9B%BE%E5%83%8F%E8%A7%A3%E7%A0%81%0A%20%20%20%20%20%20%20%20G%5BVAE%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDVAE%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20H%5BVAE%20Decode%3Cbr%2F%3EVAE%E8%A7%A3%E7%A0%81%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E8%BE%93%E5%87%BA%E5%B1%82%0A%20%20%20%20%20%20%20%20I%5BPreview%20Image%3Cbr%2F%3E%E9%A2%84%E8%A7%88%E5%9B%BE%E5%83%8F%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20A%20--%3E%20C%0A%20%20%20%20B%20--%3E%20C%0A%20%20%20%20C%20--%20AI%E8%AF%AD%E8%A8%80%3Cbr%2F%3E(conditioning)%20--%3E%20F%0A%20%20%20%20D%20--%20%E7%94%BB%E5%9B%BE%E6%A8%A1%E5%9E%8B%3Cbr%2F%3E(model)%20--%3E%20F%0A%20%20%20%20E%20--%20%E7%A9%BA%E7%99%BD%E6%BD%9C%E5%9C%A8%E5%9B%BE%E5%83%8F%3Cbr%2F%3E(latent)%20--%3E%20F%0A%20%20%20%20F%20--%20%E6%BD%9C%E5%9C%A8%E5%9B%BE%E5%83%8F%3Cbr%2F%3E(latent)%20--%3E%20H%0A%20%20%20%20G%20--%20VAE%E6%A8%A1%E5%9E%8B%3Cbr%2F%3E(vae)%20--%3E%20H%0A%20%20%20%20H%20--%20%E6%9C%80%E7%BB%88%E5%9B%BE%E5%83%8F%3Cbr%2F%3E(image)%20--%3E%20I%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%2Cstroke%3A%231976d2%0A%20%20%20%20style%20B%20fill%3A%23fce4ec%2Cstroke%3A%23c2185b%0A%20%20%20%20style%20C%20fill%3A%23fce4ec%2Cstroke%3A%23c2185b%0A%20%20%20%20style%20D%20fill%3A%23fff3e0%2Cstroke%3A%23f57c00%0A%20%20%20%20style%20E%20fill%3A%23fff3e0%2Cstroke%3A%23f57c00%0A%20%20%20%20style%20F%20fill%3A%23ffcc80%2Cstroke%3A%23e65100%0A%20%20%20%20style%20G%20fill%3A%23e8f5e9%2Cstroke%3A%23388e3c%0A%20%20%20%20style%20H%20fill%3A%23e8f5e9%2Cstroke%3A%23388e3c%0A%20%20%20%20style%20I%20fill%3A%23f3e5f5%2Cstroke%3A%237b1fa2%0A",showToolbar:"1"})]),_:1}),t[2]||(t[2]=e(`<h2 id="图生图-image-to-image" tabindex="-1">图生图（Image-to-Image） <a class="header-anchor" href="#图生图-image-to-image" aria-label="Permalink to &quot;图生图（Image-to-Image）&quot;">​</a></h2><p>图生图和文生图的区别在于起点不同：</p><ul><li><strong>文生图</strong>：从一张&quot;白纸&quot;（随机噪点图）开始去噪。</li><li><strong>图生图</strong>：从一张&quot;原图&quot;上先增加噪点，再开始去噪。</li></ul><p><span style="color:blue;">核心比喻：根据用户提供的原图和提示词，先给原图增加噪点，变成一张模糊的图片,保留原图大体结构。然后根据提示词要求，再去噪点，最终生成一张新的图像。</span></p><h3 id="基本业务逻辑" tabindex="-1">基本业务逻辑 <a class="header-anchor" href="#基本业务逻辑" aria-label="Permalink to &quot;基本业务逻辑&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入原图和提示词</span></span>
<span class="line"><span>  -&gt; 将提示词转化为AI语言。</span></span>
<span class="line"><span>  -&gt; 把AI语言和原图一起发送给图像生成模型。</span></span>
<span class="line"><span>  -&gt; 图像生成模型读取原图作为作画基础框架。先给原图叠加雪花噪点、将其变成一张模糊的图片。其中的重绘强度参数决定加噪点的程度，数值越高，原图模糊越彻底、可修改空间越大。</span></span>
<span class="line"><span>  -&gt; 图像生成模型根据你给的提示词要求，对这个模糊的图片分几十步慢慢清理噪点：每一步都修正画面、使其贴合提示词要求。</span></span>
<span class="line"><span>  -&gt; 然后将符合要求的图通过图像编码解码模型转换为人类能识别的图像结果。</span></span>
<span class="line"><span>  -&gt; 最后将生成的图像保存到本地。</span></span></code></pre></div><h3 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><blockquote><p>专业角度介绍</p></blockquote><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>- 步骤1: 输入原图和提示词</span></span>
<span class="line"><span>- 步骤2: CLIP文本编码器将提示词转换为AI语言（条件向量）</span></span>
<span class="line"><span>- 步骤3: 在模型潜空间中，先再原图的基础上叠加雪花噪点、将其变成一张模糊的图片。重绘强度决定加噪点的程度，数值越高，原图模糊越彻底、可修改空间越大。</span></span>
<span class="line"><span>- 步骤4: 采样器再根据AI语言（条件向量）逐步迭代去除潜在图像的噪点，生成清晰的潜在图像。</span></span>
<span class="line"><span>- 步骤5: VAE解码器将潜在图像转换为 RGB 像素图像</span></span>
<span class="line"><span>- 步骤6: 输出最终的 RGB 像素图像</span></span></code></pre></div><h3 id="图生图工作流示例" tabindex="-1">图生图工作流示例 <a class="header-anchor" href="#图生图工作流示例" aria-label="Permalink to &quot;图生图工作流示例&quot;">​</a></h3><p>用流程图展示图生图工作流</p>`,11)),a(o,null,{default:s(()=>[a(n,{code:"graph%20TD%0A%20%20%20%20subgraph%20%E6%96%87%E6%9C%AC%E5%9B%BE%E5%83%8F%E8%BE%93%E5%85%A5%0A%20%20%20%20%20%20%20%20A1%5BLoad%20Image%3Cbr%2F%3E%E5%8A%A0%E8%BD%BD%E5%8E%9F%E5%9B%BE%5D%0A%20%20%20%20%20%20%20%20A2%5B%E6%8F%90%E7%A4%BA%E8%AF%8D%E8%BE%93%E5%85%A5%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%0A%20%20%20%20%20%20%20%20B1%5BCLIP%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDCLIP%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20B2%5BCLIP%20Text%20Encode%3Cbr%2F%3E%E6%96%87%E6%9C%AC%E7%BC%96%E7%A0%81%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E5%9B%BE%E5%83%8F%E7%94%9F%E6%88%90%0A%20%20%20%20%20%20%20%20C1%5BUNet%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BD%E5%9B%BE%E5%83%8F%E7%94%9F%E6%88%90%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20C2%5BLoRA%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDLoRA%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20C21%5B%E7%A9%BALatent%3Cbr%2F%3E%E7%A9%BA%E6%BD%9C%E5%9C%A8%E5%9B%BE%E5%83%8F%5D%0A%20%20%20%20%20%20%20%20C3%5BKSampler%3Cbr%2F%3EK%E9%87%87%E6%A0%B7%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E5%9B%BE%E5%83%8F%E8%A7%A3%E7%A0%81%0A%20%20%20%20%20%20%20%20G%5BVAE%20Loader%3Cbr%2F%3E%E5%8A%A0%E8%BD%BDVAE%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20%20%20%20%20H%5BVAE%20Decode%3Cbr%2F%3EVAE%E8%A7%A3%E7%A0%81%E5%99%A8%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20subgraph%20%E8%BE%93%E5%87%BA%E5%9B%BE%E5%83%8F%0A%20%20%20%20%20%20%20%20I%5BPreview%20Image%3Cbr%2F%3E%E9%A2%84%E8%A7%88%E5%9B%BE%E5%83%8F%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20A1%20--%3E%20B2%0A%20%20%20%20A2%20--%3E%20B2%0A%20%20%20%20B1%20--%3E%20B2%0A%20%20%20%20B2%20--%3E%20C3%0A%20%20%20%20C1%20--%3E%20C2%0A%20%20%20%20C2%20--%3E%20C3%0A%20%20%20%20C21%20--%3E%20C3%0A%20%20%20%20G%20--%3E%20B2%0A%20%20%20%20G%20--%3E%20H%0A%20%20%20%20C3%20--%3E%20H%0A%20%20%20%20H%20--%3E%20I%0A",showToolbar:"1"})]),_:1}),t[3]||(t[3]=e(`<hr><h2 id="文生视频-text-to-video" tabindex="-1">文生视频（Text-to-Video） <a class="header-anchor" href="#文生视频-text-to-video" aria-label="Permalink to &quot;文生视频（Text-to-Video）&quot;">​</a></h2><h3 id="通俗解释" tabindex="-1">通俗解释 <a class="header-anchor" href="#通俗解释" aria-label="Permalink to &quot;通俗解释&quot;">​</a></h3><p>文生视频就像让AI画一系列连续的画，然后把它们连起来变成动画：</p><ol><li><strong>你说需求</strong>：&quot;一个女孩在草地上跑步&quot;（提示词）</li><li><strong>准备画纸</strong>：准备多张空白画纸（潜在图像序列）</li><li><strong>逐帧画画</strong>：AI一张一张画，每张画是视频的一帧</li><li><strong>保持连贯</strong>：确保相邻画面之间动作连贯（时间一致性）</li><li><strong>合成视频</strong>：把所有画连起来变成视频</li></ol><h3 id="工作原理-1" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理-1" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入提示词</span></span>
<span class="line"><span>  -&gt; CLIP文本编码器将提示词转换为AI语言（条件向量）</span></span>
<span class="line"><span>  -&gt; 模型创建空白潜在图像序列</span></span>
<span class="line"><span>  -&gt; 视频模型逐帧生成图像</span></span>
<span class="line"><span>  -&gt; 相邻帧之间添加时间一致性约束</span></span>
<span class="line"><span>  -&gt; VAE解码每帧图像</span></span>
<span class="line"><span>  -&gt; 组合成视频输出</span></span></code></pre></div><h2 id="图生视频-image-to-video" tabindex="-1">图生视频（Image-to-Video） <a class="header-anchor" href="#图生视频-image-to-video" aria-label="Permalink to &quot;图生视频（Image-to-Video）&quot;">​</a></h2><h3 id="通俗解释-1" tabindex="-1">通俗解释 <a class="header-anchor" href="#通俗解释-1" aria-label="Permalink to &quot;通俗解释&quot;">​</a></h3><p>图生视频就像让AI从一张静态照片开始，想象接下来会发生什么：</p><ol><li><strong>输入照片</strong>：一张女孩站在草地上的照片</li><li><strong>你说需求</strong>：&quot;让她跑起来&quot;（提示词）</li><li><strong>AI想象</strong>：AI根据照片和需求，生成女孩跑步的连续画面</li><li><strong>保持连贯</strong>：确保动作流畅自然</li><li><strong>合成视频</strong>：把所有画面连起来变成视频</li></ol><h3 id="工作原理-2" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理-2" aria-label="Permalink to &quot;工作原理&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入原图和提示词</span></span>
<span class="line"><span>  -&gt; VAE编码先将原图编码为潜在图像</span></span>
<span class="line"><span>  -&gt; CLIP文本编码器将提示词转换为AI语言（条件向量）</span></span>
<span class="line"><span>  -&gt; 视频模型从原图出发，逐帧生成后续画面</span></span>
<span class="line"><span>  -&gt; 相邻帧之间添加时间一致性约束</span></span>
<span class="line"><span>  -&gt; VAE解码每帧图像</span></span>
<span class="line"><span>  -&gt; 组合成视频输出</span></span></code></pre></div><h2 id="技术术语详解" tabindex="-1">技术术语详解 <a class="header-anchor" href="#技术术语详解" aria-label="Permalink to &quot;技术术语详解&quot;">​</a></h2><p>以上的文生图，图生视频中会产生许多技术术语。下面对这些术语进行介绍</p><h3 id="潜在空间图像-latent-space-image" tabindex="-1">潜在空间图像（Latent Space Image） <a class="header-anchor" href="#潜在空间图像-latent-space-image" aria-label="Permalink to &quot;潜在空间图像（Latent Space Image）&quot;">​</a></h3><p><strong>定义</strong>：一种压缩的图像表示方式，尺寸只有原图的1/8左右。</p><p><strong>通俗解释</strong>：就像把一张大图压缩成小图来处理，处理完再放大。</p><p><strong>优势</strong>：计算速度快，显存占用少</p><h3 id="vae-variational-autoencoder-变分自编码器" tabindex="-1">VAE（Variational Autoencoder,变分自编码器） <a class="header-anchor" href="#vae-variational-autoencoder-变分自编码器" aria-label="Permalink to &quot;VAE（Variational Autoencoder,变分自编码器）&quot;">​</a></h3><p><strong>定义</strong>：负责将像素图像和潜在空间图像之间进行转换的组件。</p><p><strong>通俗解释</strong>：VAE就像一个翻译器，在人类图像和AI内部图像之间转换。</p><p><strong>组成</strong>：</p><ul><li><strong>VAE编码器</strong>：将正常RGB图像编码为潜在空间图像</li><li><strong>VAE解码器</strong>：将潜在空间图像解码为正常RGB图像</li></ul><h3 id="clip-contrastive-language-image-pretraining-对比语言-图像预训练" tabindex="-1">CLIP（Contrastive Language-Image Pretraining,对比语言-图像预训练） <a class="header-anchor" href="#clip-contrastive-language-image-pretraining-对比语言-图像预训练" aria-label="Permalink to &quot;CLIP（Contrastive Language-Image Pretraining,对比语言-图像预训练）&quot;">​</a></h3><p><strong>定义</strong>：一种能够将文本和图像关联起来的模型。</p><p><strong>通俗解释</strong>：CLIP 是AI的&quot;双语词典&quot;，知道哪些文字对应哪些图像。</p><p><strong>作用</strong>：CLIP文本编码器负责将提示词转换为条件向量，引导图像生成。</p><h3 id="unet" tabindex="-1">UNet <a class="header-anchor" href="#unet" aria-label="Permalink to &quot;UNet&quot;">​</a></h3><p><strong>定义</strong>：Diffusion模型中负责去噪的核心组件。</p><p><strong>通俗解释</strong>：UNet是AI的&quot;画笔&quot;，负责根据提示词一步步去除噪点，生成清晰的潜在图像。</p><p><strong>特点</strong>：</p><ul><li>接受条件向量和潜在图像作为输入</li><li>输出去噪后的潜在图像</li></ul><h3 id="seed-随机种子" tabindex="-1">seed 随机种子 <a class="header-anchor" href="#seed-随机种子" aria-label="Permalink to &quot;seed 随机种子&quot;">​</a></h3><p><strong>核心作用</strong>：决定图片初始噪点的排列规律，相当于画面的 “基因编号”。同一个种子 + 完全相同的其他参数，能 100% 复现同一张图。同一个种子值 + 不同的配置参数，会导致不同的画面效果。</p><p>如图所示，不同的随机种子，会导致不同的画面的初始噪声图，进而导致最终的画面效果。 <img src="`+k+'" alt="stablediffusion_2026-07-17_173507_595.png" loading="lazy"></p><span style="color:red;"> 注意事项：随机种子的取值范围是 0-4294967295。如果设置为-1,则表示每次生成图片时，都会随机生成种子。生成出来的图片都有一个自己的种子值。 </span><blockquote><p>随机种子使用建议</p></blockquote><ul><li>找灵感阶段：seed数值设置为-1，那么种子值会随机生成，然后再配合批量出图，挑选出满意的构图和氛围。</li><li>微调图片阶段：先固定种子数值，只修改提示词/小参数，保证画面整体构图不变、只调整画面细节，这样效率最高。</li></ul><h3 id="采样-sampling" tabindex="-1">采样（Sampling） <a class="header-anchor" href="#采样-sampling" aria-label="Permalink to &quot;采样（Sampling）&quot;">​</a></h3><h4 id="什么是采样" tabindex="-1">什么是采样？ <a class="header-anchor" href="#什么是采样" aria-label="Permalink to &quot;什么是采样？&quot;">​</a></h4><p>diffusion扩散模型生成图片的过程是： 先随机生成一个噪声图像 -&gt; 然后根据提示词去除噪声 -&gt; 最后生成具体的图像。</p><p>如图是采样的过程。图片在每一次迭代中，都会被去除一些噪声。每一次迭代都会让图片更接近最终的图像。 <img src="'+m+'" alt="stablediffusion_2026-07-17_164931_305.png" loading="lazy"></p><p><span style="color:red;">简而言之，采样就是图像生成中去除噪声，生成清晰图像的过程。</span></p><p><a href="https://stable-diffusion-art.com/samplers/" target="_blank" rel="noreferrer">具体详细的采样介绍，可以参考 https://stable-diffusion-art.com/samplers/</a>。</p><h4 id="什么是采样器-sampler" tabindex="-1">什么是采样器（Sampler）？ <a class="header-anchor" href="#什么是采样器-sampler" aria-label="Permalink to &quot;什么是采样器（Sampler）？&quot;">​</a></h4><p><strong>定义</strong>：采样器就是在图像生成过程中，根据提示词去除噪声的算法。不同的采样器使用不同的采样算法来去除噪声。</p><p><strong>通俗解释</strong>：不同的采样器就像不同的画画风格，有的画得快，有的画得细致。</p><blockquote><p>如何选择采样器?</p></blockquote><p>目前有许多采样器，但是这些采样器有的已经过时，有的效果不好。建议绝大多数情况下，选择默认的采样器即可。</p><p><strong>目前仅推荐以下几种采样器</strong>：</p><table tabindex="0"><thead><tr><th>采样器</th><th>特点</th><th>类比</th></tr></thead><tbody><tr><td>DPM++ 2M</td><td>最常用的采样器，平衡效果和质量，速度快。相对全能的一个采样器。推荐使用。</td><td>素描</td></tr><tr><td>DPM++ SDE</td><td>高质量，适合最终渲染</td><td>油画</td></tr><tr><td>Euler</td><td>快速，适合预览</td><td>速写</td></tr><tr><td>Euler a</td><td>在Euler采样器的基础上，添加了一些改进。随机性强，创意丰富</td><td>写意画</td></tr><tr><td>Restart</td><td>新一代采样器，效率高，可以在较少的迭代步数上就能够生成高质量的图像。</td><td>速写</td></tr></tbody></table><h3 id="采样步数-即采样迭代次数" tabindex="-1">采样步数（即采样迭代次数） <a class="header-anchor" href="#采样步数-即采样迭代次数" aria-label="Permalink to &quot;采样步数（即采样迭代次数）&quot;">​</a></h3><p><strong>核心作用</strong>：决定采样器在图像上迭代的次数。简而言之就是 AI 迭代画面的次数。步数越少迭代次数越少，生成越快，步数越多迭代次数越多，生成越慢，细节越完整。</p><p><span style="color:red;">注意：采样步数与采样器和调度器的选择相关。不同的模型对应的采样步数的推荐值是不同的。对于大多数模型来说，采样步数的推荐值是25步左右。但达到一定步数后再加步数，画面几乎不会提升,边际效果减少，纯浪费时间。</span></p><blockquote><p>不同模型对应采样步数的推荐值：</p></blockquote><ul><li>SD-1.5模型：20~28 步</li><li>SDXL模型：24~35步</li><li>Z-Image-Turbo模型：8步</li><li>Wan2.1模型：24~28步</li></ul><h3 id="调度器-scheduler" tabindex="-1">调度器（Scheduler） <a class="header-anchor" href="#调度器-scheduler" aria-label="Permalink to &quot;调度器（Scheduler）&quot;">​</a></h3><p><strong>定义</strong>：调度器就是在图像生成的每一次迭代过程中，根据采样器的结果，调度器决定了下一次迭代中去噪的幅度和方式。</p><blockquote><p>如何选择调度器?</p></blockquote><p>大多情况下，调度器可以选默认即可。即程序会根据采样器的选择来选择合适的调度器。或者拿不准的时候，可以选择Karras调度器。</p><ul><li>Karras: 最常用的调度器，效果好，速度快，相对全能的一个调度器。推荐使用。</li></ul><p><span style="color:red;">注意：不同的模型需要搭配不同的采样器和调度器。因为模型在训练时，会更倾向使用某种采样器和调度器。具体可以参考模型的文档，或者参考模型作者的建议。</span></p><h3 id="cfg-提示词强度" tabindex="-1">cfg 提示词强度 <a class="header-anchor" href="#cfg-提示词强度" aria-label="Permalink to &quot;cfg 提示词强度&quot;">​</a></h3><p><strong>定义</strong>：控制提示词对生成结果的影响程度。CFG数值越低，AI 越自由发挥；数值越高，越严格贴合你写的提示词描述。</p><p><strong>常见范围</strong>：5-15，推荐7-10</p><ul><li>太低（&lt; 3）：提示词几乎失效，画面随机感强，内容容易跑偏。</li><li>太高（&gt;10）：画面僵硬、色彩过饱和、细节重复（俗称 “CFG 烧了”），反而会变糊、出现畸形元素。</li></ul><p><span style="color:red;">注意：先按模型文档中推荐的cfg值来，觉得画面不符合描述就加 0.5~1，觉得画面僵硬不自然就减 0.5~1。</span></p><blockquote><p>不同模型对应CFG的推荐值：</p></blockquote><ul><li>SD-1.5模型：建议5~7。首选6</li><li>SDXL模型：建议5~8。首选7</li><li>Z-Image-Turbo模型：3~5。首选4</li><li>Wan2.1模型：6~7</li></ul><h3 id="denoise-去噪强度-降噪强度" tabindex="-1">Denoise（去噪强度，降噪强度） <a class="header-anchor" href="#denoise-去噪强度-降噪强度" aria-label="Permalink to &quot;Denoise（去噪强度，降噪强度）&quot;">​</a></h3><p><strong>定义</strong>：由于图生图是需要先对原图添加噪声的。降噪强度就是对原图添加噪声的修改程度。数值越大，AI对原图的修改越多；值越小，保留原图越多。数值范围是0 ~ 1。</p><p><span style="color:red;">注意：降噪强度Denoise 在文生图的场景下无效。因为文生图是没有原图的。</span></p><blockquote><p>适用范围</p></blockquote><table tabindex="0"><thead><tr><th>Denoise值</th><th>效果</th><th>类比</th></tr></thead><tbody><tr><td>0.1~0.3</td><td>只优化画质、光影、色彩，构图主体几乎不变（比如照片修复、提清晰度）</td><td>微改动</td></tr><tr><td>0.3~0.5</td><td>轻微修改，保留主体构图，更换画风、细化细节（比如照片转动漫）。</td><td>小改</td></tr><tr><td>0.5~0.7</td><td>中等修改，主体大致保留，细节和背景大幅修改。</td><td>中改</td></tr><tr><td>0.7~0.9</td><td>较大修改，主体只保留大致轮廓，几乎重新创作。</td><td>大改</td></tr><tr><td>0.9 以上</td><td>完全重绘,接近纯文生图参考图只剩极浅的影子。</td><td>重画</td></tr></tbody></table>',75))])}const S=i(B,[["render",C]]);export{L as __pageData,S as default};
